import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"睽","description":"周易集解 - 睽","frontmatter":{"title":"睽","description":"周易集解 - 睽"},"headers":[],"relativePath":"zh/classics/jijie/038.md","filePath":"zh/classics/jijie/038.md"}'),l={name:"zh/classics/jijie/038.md"};function n(p,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="睽" tabindex="-1">睽 <a class="header-anchor" href="#睽" aria-label="Permalink to “睽”">​</a></h1><h2 id="睽-1" tabindex="-1">睽 <a class="header-anchor" href="#睽-1" aria-label="Permalink to “睽”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>睽，小事吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：家道窮必乖，故受之以睽。睽者，乖也。</p><p>崔憬曰：婦子嘻嘻，過在失節。失節則窮，窮則乖，故曰｢家道窮必乖｣。</p><p>虞翻曰：大壯上之三在繫，蓋取無妄二之五也。小謂五。陰稱小，得中應剛，故吉。</p><p>鄭玄曰：睽，乖也。火欲上，澤欲下，猶人同居而志異也，故謂之睽。二五相應，君陰臣陽，君而應臣，故小事吉。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：睽，火動而上，澤動而下。二女同居，其志不同行。說而麗乎明，柔進而上行，得中而應乎剛，是以小事吉。天地睽而其事同也。男女睽而其志通也。萬物睽而其事類也。睽之時用大矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>虞翻曰：離火炎上，澤水潤下也。</p><p>虞翻曰：二女，離兌也。坎為志。離上兌下。無妄震為行，巽為同，艮為居。二五易位，震巽象壞。故｢二女同居，其志不同行也｣。</p><p>虞翻曰：說，兌。麗，離也。明謂乾。當言大明以麗於晉。柔謂五，無妄巽為進。從二之五，故上行。剛謂應乾，五伏陽，非應二也。與鼎五同義也。</p><p>荀爽曰：小事者，臣事也。百官異體，四民殊業，故睽而不同。剛者，君也。柔得其中，而進於君，故言小事吉也。</p><p>王肅曰：高卑雖異，同育萬物。</p><p>虞翻曰：五動乾為天，四動坤為地，故天地睽。坤為事也。五動體同人，故事同矣。</p><p>侯果曰：出處雖殊，情通志合。</p><p>虞翻曰：四動艮為男，兌為女，故男女睽。坎為志，為通，故其志通也。</p><p>崔憬曰：萬物雖睽於形色，而生性事類言亦同也。</p><p>虞翻曰：四動，萬物出乎震，區以別矣。故萬物睽。坤為事，為類，故其事類也。</p><p>《九家易》曰：乖離之卦，於義不大。而天地事同，共生萬物，故曰用大。</p><p>盧氏曰：不言義而言用者，明用睽之義至大矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：上火下澤，睽。君子以同而異。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：火性炎上，澤性潤下，故曰睽也。</p><p>荀爽曰：大歸雖同，小事當異。百家殊職，四民異業。文武並用，威德相反，共歸於治，故曰君子以同而異也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，悔亡，喪馬，勿逐，自復。見惡人，無咎。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：見惡人，以避咎也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：無應，悔也。四動得位，故悔亡。應在於坎，坎為馬。四而失位，之正入坤，坤為喪。坎象不見，故喪馬。震為逐，艮為止，故勿逐。坤為自，二至五，體復象，故自復。四動震馬來，故勿逐自復也。離為見。惡人謂四，動入坤初，四復正。故「見惡人，以避咎矣｣。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，遇主於巷，無咎。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：二動體震。震為主，為大塗，艮為徑路。大道而有徑路，故稱巷。變而得正，故無咎而未失道也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：遇主於巷，未失道也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：動得正，故未失道。</p><p>崔憬曰：處睽之時，與五有應。男女雖隔，其志終通。而三比焉，近不相得。遇者，不期而會。主者，三為下卦之主。巷者，出門近遇之象。言二遇三，明非背五，未為失道也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，見輿曳，其牛掣。其人天且劓，無初有終。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：離為見。坎為車，為曳。故見輿曳。四動坤為牛，為類。牛角一低一仰，故稱掣。離上而坎下，其牛掣也。</p><p>虞翻曰：其人謂四，惡人也。黥額為天，割鼻為劓。無妄乾為天。震二之乾五，以陰墨其天。乾五之震二，毀艮，割其鼻也。兌為刑人。故其人天且劓。失位，動得正成乾，故無初有終。《象》曰｢遇剛｣，是其義也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：見輿曳，位不當也。無初有終，遇剛也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：動正成乾，故遇剛。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，睽孤，遇元夫，交孚，厲，無咎。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：孤，顧也。在兩陰間，睽五顧三，故曰睽孤。震為元夫。謂二已變，動而應震。故遇元夫也。震為交，坎為孚，動而得正，故｢交孚，厲，無咎｣矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：交孚無咎，志行也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坎動成震，故志行也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，悔亡，厥宗噬膚，往何咎。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：往得位，悔亡也。動而之乾，乾為宗。二體噬嗑，故曰噬。四變時，艮為膚。故曰｢厥宗噬膚｣也。變得正成乾，乾為慶，故往無咎而有慶矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：厥宗噬膚，往有慶也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>王弼曰：非位悔也。有應，故悔亡。厥宗謂二也。噬膚者，齧柔也。三雖比二，二之所噬，非妨已應者也。以斯而往，何咎之有。往必見合，故有慶也。</p><p>案：二兌為口，五爻陰柔，噬膚之象也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，睽孤，見豕負塗，載鬼一車。先張之弧，後說之壺，匪寇婚媾。往，遇雨則吉。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：睽三顧五，故曰睽孤也。離為見，坎為豕，為雨。四變時坤為土，土得雨，為泥塗。四動艮為背，豕背有泥，故見豕負塗矣。坤為鬼，坎為車，變在坎上，故載鬼一車也。</p><p>虞翻曰：謂五已變，乾為先。應在三。坎為弧，離為矢腹，張弓之象也，故先張之弧。四動震為後。說，猶置也。兌為口，離為大腹，坤為器。大腹有口。坎，酒在中，壺之象也。之應歷險以與兌。故後說之壺矣。</p><p>虞翻曰：匪，非；坎為寇，之三歷坎，故匪寇。陰陽相應，故婚媾。三在坎下，故遇雨。與上易位，坎象不見，各得其正，故則吉也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：遇雨之吉，群疑亡也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：物三稱群，坎為疑，三變坎敗，故群疑亡矣。</p>',80)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
